pub fn decode_words(node: &Node) -> Result<Words, DecodeError> {
    let (name, arguments) = support::any_call(
        node,
        |name| !name.split(' ').any(|word| word == "_"),
        "a call with no arguments",
    )?;
    Ok(Words {
        name,
        arguments: arguments.to_vec(),
        span: node.span,
    })
}

